/**
 * Applies physics body attributes to any UsdGeomXformable prim and
 * marks that prim to be driven by a simulation. If a simulation is running
 * it will update this prim's pose. All prims in the hierarchy below this 
 * prim should move rigidly along with the body, except when the descendant
 * prim has its own UsdPhysicsRigidBodyAPI (marking a separate rigid body
 * subtree which moves independently of the parent rigid body).
 */
export class RigidBodyAPI extends APISchemaBase {
  static readonly typeName: string = "PhysicsRigidBodyAPI"

  static get(stage: Stage, path: string): RigidBodyAPI {
    return new RigidBodyAPI(stage.getPrim(path), stage)
  }

  isValid(): boolean {
    return super.isValid() && this.prim.hasAPI(RigidBodyAPI.typeName)
  }

  static canApply(prim: Prim): boolean {
    return prim.canApplyAPI(RigidBodyAPI.typeName)
  }
  static apply(prim: Prim): RigidBodyAPI {
    if (prim.applyAPI(RigidBodyAPI.typeName)) return new RigidBodyAPI(prim, prim.getStage())
    return new RigidBodyAPI(undefined, prim.getStage())
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? ["physics:rigidBodyEnabled","physics:kinematicEnabled","physics:startsAsleep","physics:velocity","physics:angularVelocity"]
      : ["physics:rigidBodyEnabled","physics:kinematicEnabled","physics:startsAsleep","physics:velocity","physics:angularVelocity"]
    return names
  }

  /**
   * Determines if this PhysicsRigidBodyAPI is enabled.
   */
  getRigidBodyEnabledAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsRigidBodyEnabled)!
  }
  createRigidBodyEnabledAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsRigidBodyEnabled, "bool", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Determines whether the body is kinematic or not. A kinematic 
   * body is a body that is moved through animated poses or through 
   * user defined poses. The simulation derives velocities for the
   * kinematic body based on the external motion. When a continuous motion
   * is not desired, this kinematic flag should be set to false.
   */
  getKinematicEnabledAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsKinematicEnabled)!
  }
  createKinematicEnabledAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsKinematicEnabled, "bool", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Determines if the body is asleep when the simulation starts.
   */
  getStartsAsleepAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsStartsAsleep)!
  }
  createStartsAsleepAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsStartsAsleep, "bool", false, "uniform", defaultValue, writeSparsely)
  }

  /**
   * Linear velocity in the same space as the node's xform. 
   * Units: distance/second.
   */
  getVelocityAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsVelocity)!
  }
  createVelocityAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsVelocity, "vector3f", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Angular velocity in the same space as the node's xform. 
   * Units: degrees/second.
   */
  getAngularVelocityAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsAngularVelocity)!
  }
  createAngularVelocityAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsAngularVelocity, "vector3f", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Single PhysicsScene that will simulate this body. By 
   * default this is the first PhysicsScene found in the stage using 
   * UsdStage::Traverse().
   */
  getSimulationOwnerRel(): Rel {
    return this.prim.rel(UsdPhysicsTokens.physicsSimulationOwner)
  }
  createSimulationOwnerRel(): Rel {
    return this.prim.createRelationship(UsdPhysicsTokens.physicsSimulationOwner, false)
  }

  // --(BEGIN CUSTOM CODE)--

  // Compute mass properties of the rigid body (rigidBodyAPI.h:315-323,
  // rigidBodyAPI.cpp:451-646). massInfoFn is the callback to get collision
  // mass information. Upstream returns the mass and writes the diagonal
  // inertia, center of mass and principal axes through out-parameters; this
  // returns them in the order of the Python binding's tuple
  // (wrapRigidBodyAPI.cpp:203-211): [mass, diagonalInertia, centerOfMass,
  // principalAxes].
  computeMassProperties(massInfoFn: MassInformationFn): [number, GfVec3f, GfVec3f, GfQuatf] {
    const usdPrim = this.prim
    const stage = usdPrim.getStage()

    const xfCache = new XformCache(stage)

    // Parse dynamic body mass data
    const rigidBodyMassInfo = _parseMassApi(usdPrim)

    // If we dont have mass, we need to compute mass from collisions
    const accumulateMass = rigidBodyMassInfo.mass <= 0.0

    // Get initial data from parsed rigid body mass information
    let outCenterOfMass = new GfVec3f(0.0)
    const hasPa = rigidBodyMassInfo.hasPa
    let outPrincipalAxes = rigidBodyMassInfo.principalAxes
    const comOut = { value: outCenterOfMass }
    const hasCoM = _getCoM(usdPrim, comOut, xfCache)
    outCenterOfMass = comOut.value
    let outMass = rigidBodyMassInfo.mass
    let outDiagonalizedInertiaTensor = new GfVec3f(rigidBodyMassInfo.diagonalInertia)

    // if we dont have enough mass information, we need to traverse collisions
    // to gather final mass information
    if (accumulateMass || !rigidBodyMassInfo.hasInertia || !hasCoM) {
      const massProps: MassProperties[] = []
      const massTransf: GfMatrix4f[] = []
      const collisionPrims: Prim[] = []

      // traverse all collisions below this body and get their collision information
      // first gather all collisions
      const range = PrimRange.fromPrim(usdPrim, TraverseInstanceProxies())
      const it = range[Symbol.iterator]()
      for (let r = it.next(); !r.done; r = it.next()) {
        const collisionPrim = r.value
        if (collisionPrim && collisionPrim.path !== usdPrim.path &&
          collisionPrim.hasAPI(RigidBodyAPI.typeName)) {
          // A nested rigid body only forms the root of its own subtree
          // while it is enabled. A disabled body takes no part in
          // simulation, so it does not own colliders; its subtree still
          // belongs to this body and must be traversed, otherwise the
          // colliders below it would contribute mass to no body at all.
          const nestedBodyAPI = new RigidBodyAPI(collisionPrim)
          let nestedBodyEnabled = true
          const v = nestedBodyAPI.getRigidBodyEnabledAttr()?.get()
          if (typeof v === 'boolean') nestedBodyEnabled = v
          if (nestedBodyEnabled) {
            it.pruneChildren() // Skip the subtree rooted at this prim,
            // the colliders belong to a different
            // rigid body
            continue
          }
        }

        if (collisionPrim && collisionPrim.hasAPI(CollisionAPI.typeName)) {
          const collisionAPI = new CollisionAPI(collisionPrim)
          let collisionEnabled = true
          const v = collisionAPI.getCollisionEnabledAttr()?.get()
          if (typeof v === 'boolean') collisionEnabled = v
          if (!collisionEnabled) {
            continue
          }

          collisionPrims.push(collisionPrim)
        }
      }

      // get materials for all prims
      // UsdShadeMaterialBindingAPI::ComputeBoundMaterials resolves each prim
      // as ComputeBoundMaterial does (materialBindingAPI.cpp); it is applied
      // per prim here.
      const physicsMaterials: (Prim | undefined)[] = collisionPrims.map(prim => {
        const bound = MaterialBindingAPI.computeBoundMaterial(stage, prim.path, _materialPurposePhysics)
        const material = bound ? stage.getPrim(bound.materialPath) : undefined
        return material && material.isA(Material.typeName) ? material : undefined
      })
      for (let i = 0; i < physicsMaterials.length; i++) {
        const material = physicsMaterials[i]
        if (material && !material.hasAPI(MaterialAPI.typeName)) {
          physicsMaterials[i] = undefined
        }
      }

      for (let i = 0; i < collisionPrims.length; i++) {
        const collisionPrim = collisionPrims[i]!
        const collisionAPI = new CollisionAPI(collisionPrim)
        const shapeDensity = { value: 0.0 }

        const massApiData =
          _getCollisionShapeMassAPIData(collisionAPI, rigidBodyMassInfo.density, shapeDensity, physicsMaterials[i])

        const matrix = { value: new GfMatrix4f() }
        massProps.push(_parseCollisionShapeForMass(collisionPrim, massApiData, shapeDensity.value, matrix, xfCache, massInfoFn))
        massTransf.push(matrix.value)
      }

      if (massProps.length !== 0) {
        // compute accumulated mass properties from all gathered collisions
        const accumulatedMassProps = MassProperties.sum(massProps, massTransf, massProps.length)

        // if we had to compute mass, set the new mass
        if (accumulateMass) {
          outMass = accumulatedMassProps.getMass()
        } else {
          // otherwise scale inertia based on the given body mass
          const massDiff = Math.fround(outMass / accumulatedMassProps.getMass())
          accumulatedMassProps.setMass(outMass)
          accumulatedMassProps.setInertiaTensor(accumulatedMassProps.getInertiaTensor().getScalarMultiply(massDiff))
        }

        if (!hasCoM) {
          // get CoM from the accumulated props
          outCenterOfMass = accumulatedMassProps.getCenterOfMass()
        } else {
          // otherwise translae the mass props by given body CoM
          accumulatedMassProps.translate(outCenterOfMass.subtract(accumulatedMassProps.getCenterOfMass()))
        }

        const accPa = new GfQuatf()
        const accInertia = MassProperties.getMassSpaceInertia(accumulatedMassProps.getInertiaTensor(), accPa)

        // check for inertia override
        if (!rigidBodyMassInfo.hasInertia) {
          // if no inertia was given to the rigid body get the accumulated inertia
          outDiagonalizedInertiaTensor = accInertia
        }

        if (!hasPa) {
          // if no prinicipal axes were given to the rigid body get the accumulated one
          outPrincipalAxes = accPa
        }
      } else {
        // no shape provided check inertia
        if (!rigidBodyMassInfo.hasInertia) {
          // In the absence of collision shapes and a specified inertia tensor, approximate
          // the tensor using a sphere. If the mass is not specified
          // throw a warning instead. Equation for spherical intertial tensor is (2/5 or
          // 0.4)*mass*radius^2, where we use 0.1 radius to imitate point.

          if (outMass > 0.0) {
            const metersPerUnit = Math.fround(getStageMetersPerUnit(stage))
            const radius = Math.fround(0.1 / metersPerUnit)
            const inertiaVal = Math.fround(0.4 * outMass * radius * radius)
            outDiagonalizedInertiaTensor = new GfVec3f(inertiaVal, inertiaVal, inertiaVal)
            TfRaiseWarning(
              `The rigid body at ${usdPrim.path} has a possibly invalid inertia tensor of {1.0, 1.0, 1.0}, small sphere approximated inertia was used. ` +
              'Either specify correct values in the mass properties, or add collider(s) to any shape(s) that you wish to automatically compute mass properties for. ' +
              "If you do not want the objects to collide, add colliders regardless then disable the 'enable collision' property.")
          } else {
            TfRaiseWarning(
              `The rigid body at ${usdPrim.path} has a possibly invalid inertia tensor of {1.0, 1.0, 1.0}${(outMass < 0.0) ? ' and a negative mass' : ''}. ` +
              'Either specify correct values in the mass properties, or add collider(s) to any shape(s) that you wish to automatically compute mass properties for. ' +
              "If you do not want the objects to collide, add colliders regardless then disable the 'enable collision' property.")
          }
        }
      }
    }

    return [outMass, outDiagonalizedInertiaTensor, outCenterOfMass, outPrincipalAxes]
  }
}

import {
  IsClose as GfIsClose, GfCompMult, Matrix3f as GfMatrix3f, Matrix4d as GfMatrix4d,
  Matrix4f as GfMatrix4f, Quatf as GfQuatf, Transform as GfTransform, Vec3f as GfVec3f,
} from 'typescript-usd/gf'
import { RaiseWarning as TfRaiseWarning } from 'typescript-usd/tf'
import { PrimRange, TraverseInstanceProxies } from 'typescript-usd/usd'
import { getStageMetersPerUnit, XformCache } from 'typescript-usd/usdGeom'
import { Material, MaterialBindingAPI } from 'typescript-usd/usdShade'
import { CollisionAPI } from './collisionAPI.ts'
import { MassAPI } from './massAPI.ts'
import { MassProperties } from './massProperties.ts'
import { MaterialAPI } from './materialAPI.ts'
import { getStageKilogramsPerUnit } from './metrics.ts'

// Mass information for a collision, used in ComputeMassProperties
// MassInformationFn callback (rigidBodyAPI.h:301-309).
export interface MassInformation {
  volume: number // Collision volume
  inertia: GfMatrix3f // Collision inertia
  centerOfMass: GfVec3f // Collision center of mass
  localPos: GfVec3f // Collision local position with respect to the rigid body
  localRot: GfQuatf // Collision local rotation with respect to the rigid body
}

// Mass information function signature, for given UsdPrim gather
// MassInformation (rigidBodyAPI.h:311-313).
export type MassInformationFn = (prim: Prim) => MassInformation

// rigidBodyAPI.cpp:245-248
const _materialPurposePhysics = 'physics'

// rigidBodyAPI.cpp:251
const COMPARE_TOLERANCE = Math.fround(1e-05)

// rigidBodyAPI.cpp:253-261
interface _MassApiData {
  mass: number
  density: number
  hasInertia: boolean
  diagonalInertia: GfVec3f
  hasPa: boolean
  principalAxes: GfQuatf
}

function _toVec3f(v: unknown, fallback: GfVec3f): GfVec3f {
  if (v instanceof GfVec3f) return v
  if (v !== null && typeof v === 'object' && 'data' in v) return new GfVec3f((v as { data: number[] }).data)
  if (Array.isArray(v) && v.length === 3) return new GfVec3f(v as number[])
  return fallback
}

function _toQuatf(v: unknown, fallback: GfQuatf): GfQuatf {
  if (v instanceof GfQuatf) return v
  if (v !== null && typeof v === 'object' && 'GetReal' in v) return new GfQuatf(v as GfQuatf)
  return fallback
}

// gather all the mass information for the gien prim, based on UsdPhysicsMassAPI
// (rigidBodyAPI.cpp:263-304)
function _parseMassApi(usdPrim: Prim): _MassApiData {
  const result: _MassApiData = {
    mass: -1.0,
    density: -1.0,
    hasInertia: false,
    diagonalInertia: new GfVec3f(1.0, 1.0, 1.0),
    hasPa: false,
    principalAxes: new GfQuatf(),
  }

  if (usdPrim.hasAPI(MassAPI.typeName)) {
    // density
    const massAPI = new MassAPI(usdPrim)
    const densityAttribute = massAPI.getDensityAttr()
    const massAttribute = massAPI.getMassAttr()
    const diagonalInertia = massAPI.getDiagonalInertiaAttr()
    const principalAxes = massAPI.getPrincipalAxesAttr()

    const density = densityAttribute?.get()
    if (typeof density === 'number') result.density = Math.fround(density)

    // An unauthored float with no fallback leaves `m` uninitialized upstream;
    // the schema provides a fallback of 0.
    const mv = massAttribute?.get()
    const m = typeof mv === 'number' ? Math.fround(mv) : 0
    if (m > 0.0) {
      result.mass = m
    }

    const dg = _toVec3f(diagonalInertia?.get(), new GfVec3f(0.0))
    if (!GfIsClose(dg, new GfVec3f(0.0), COMPARE_TOLERANCE)) {
      result.hasInertia = true
      result.diagonalInertia = dg
    }

    // 0 0 0 0 is the sentinel value
    const pa = _toQuatf(principalAxes?.get(), new GfQuatf())
    if (!GfIsClose(pa.GetImaginary(), new GfVec3f(0.0), COMPARE_TOLERANCE) || Math.abs(pa.GetReal()) > COMPARE_TOLERANCE) {
      result.hasPa = true
      result.principalAxes = pa
    }
  }
  return result
}

// custom get center of mass, using also transformation to apply scaling
// (rigidBodyAPI.cpp:306-334). `com` is the upstream out-parameter.
function _getCoM(usdPrim: Prim, com: { value: GfVec3f }, xfCache: XformCache): boolean {
  let comSet = false
  if (usdPrim.hasAPI(MassAPI.typeName)) {
    // com
    const massAPI = new MassAPI(usdPrim)
    const comAttribute = massAPI.getCenterOfMassAttr()

    const v = _toVec3f(comAttribute?.get(), new GfVec3f(-Infinity, -Infinity, -Infinity))

    // -inf -inf -inf is the sentinel value, though any inf works
    if (Number.isFinite(v.get(0)) && Number.isFinite(v.get(1)) && Number.isFinite(v.get(2))) {
      // need to extract scale as physics in general does not support scale,
      //we need to scale the com
      const mat = new GfMatrix4d(...xfCache.getLocalToWorldTransform(usdPrim))
      const tr = new GfTransform(mat)
      const sc = new GfVec3f(tr.getScale())

      com.value = GfCompMult(v, sc)

      comSet = true
    }
  }
  return comSet
}

// get density form a collision prim, it will also check its materials eventually
// (rigidBodyAPI.cpp:336-365). `density` is the upstream out-parameter.
function _getCollisionShapeMassAPIData(collisionAPI: CollisionAPI,
  bodyDensity: number, density: { value: number }, materialPrim: Prim | undefined): _MassApiData {
  const shapeMassInfo = _parseMassApi(collisionAPI.prim)
  if (shapeMassInfo.density <= 0.0) {
    // use parent density if shape doesn't have one specified
    shapeMassInfo.density = bodyDensity
  }

  // handle material
  density.value = shapeMassInfo.density
  if (shapeMassInfo.density <= 0.0) { // density not set, so we take it from the materials
    if (materialPrim) {
      const materialAPI = new MaterialAPI(materialPrim)

      if (materialAPI.isValid()) {
        const densityAttr = materialAPI.getDensityAttr()
        const d = densityAttr?.get()
        if (typeof d === 'number') density.value = Math.fround(d)
      }
    }
  }

  return shapeMassInfo
}

// gather mass information for given collision shape
// (rigidBodyAPI.cpp:367-449). `transform` is the upstream out-parameter.
function _parseCollisionShapeForMass(prim: Prim, inShapeMassInfo: _MassApiData, density: number,
  transform: { value: GfMatrix4f }, xformCache: XformCache, massInfoFn: MassInformationFn): MassProperties {
  const shapeMassInfo = { ...inShapeMassInfo }

  // Get the actuall mass information for the prim
  const massInfo = { ...massInfoFn(prim) }
  if (massInfo.volume < 0.0) {
    TfRaiseWarning(`Provided mass information not valid for a prim ${prim.path}.`)

    return new MassProperties()
  }

  let inertia = new GfMatrix3f(massInfo.inertia)

  // if no density was set, use default based on units
  if (density <= 0.0) {
    // default density 1000.0 kg / meters * meters * meters
    const metersPerUnit = Math.fround(getStageMetersPerUnit(prim.getStage()))
    const kgPerUnit = Math.fround(getStageKilogramsPerUnit(prim.getStage()))
    density = Math.fround(1000.0 * metersPerUnit * metersPerUnit * metersPerUnit / kgPerUnit)
  }

  const centerOfMass = { value: new GfVec3f(0.0) }
  const principalAxes = new GfQuatf(1.0)
  const hasCoM = _getCoM(prim, centerOfMass, xformCache)

  // we have a collider mass override
  if (shapeMassInfo.mass > 0.0) {
    inertia = inertia.getScalarMultiply(Math.fround(shapeMassInfo.mass / massInfo.volume))
  } else if (massInfo.volume >= 0.0) {
    // we dont have mass compute it based on the collision volume
    shapeMassInfo.mass = Math.fround(massInfo.volume * density)
    inertia = inertia.getScalarMultiply(density)
  }

  // inertia was provided, update the inertia data
  if (shapeMassInfo.hasInertia) {
    const im = principalAxes.GetImaginary()
    const rotMatr = new GfMatrix3f([principalAxes.GetReal(), im.get(0), im.get(1), im.get(2)])
    const inMatr = new GfMatrix3f(0.0)
    inMatr.SetElement(0, 0, shapeMassInfo.diagonalInertia.get(0))
    inMatr.SetElement(1, 1, shapeMassInfo.diagonalInertia.get(1))
    inMatr.SetElement(2, 2, shapeMassInfo.diagonalInertia.get(2))

    inertia = inMatr.getMultiply(rotMatr)
  }

  if (shapeMassInfo.hasPa) {
    inertia = MassProperties.rotateInertia(inertia, shapeMassInfo.principalAxes)
  }

  // center of mass provided, update the inertia
  if (hasCoM) {
    if (!shapeMassInfo.hasInertia) {
      // update inertia if we override the CoM but use the computed inertia
      const massProps = new MassProperties(shapeMassInfo.mass, inertia, massInfo.centerOfMass)
      massProps.translate(centerOfMass.value.subtract(massProps.getCenterOfMass()))
      inertia = massProps.getInertiaTensor()
    }
    massInfo.centerOfMass = centerOfMass.value
  }

  // setup collision transformation
  const lr = massInfo.localRot
  const lri = lr.GetImaginary()
  transform.value.setTranslate(massInfo.localPos)
  transform.value.setRotateOnly([lr.GetReal(), lri.get(0), lri.get(1), lri.get(2)])

  // return final collision mass properties
  return new MassProperties(shapeMassInfo.mass, inertia, massInfo.centerOfMass)
}
